a9k(a,b){return a+": \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u043e "+b+" \u0442\u043e\u0432\u0430\u0440\u043e\u0432"},
ga9j(){return"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c \u043a\u0430\u0442\u0430\u043b\u043e\u0433. \u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442."},
gVD(){return"\u0426\u0435\u043d\u0430, \u20ac"},
