gYF(){return"\u0420\u0435\u0436\u0438\u043c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430: \u044d\u043a\u0440\u0430\u043d \u043d\u0435 \u043f\u043e\u0433\u0430\u0441\u043d\u0435\u0442"},
gYE(){return"\u0420\u0435\u0436\u0438\u043c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430 \u0432\u044b\u043a\u043b\u044e\u0447\u0435\u043d"},
UF(a){return"\xab"+a+"\xbb \u0443\u0434\u0430\u043b\u0451\u043d"},
gvz(){return"\u041e\u0442\u043c\u0435\u043d\u0438\u0442\u044c"},
